const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

export function validateEmail(email: string): string | null {
  const value = email.trim();
  if (!value) return "Please enter your email address";
  if (!EMAIL_RE.test(value)) return "Please enter a valid email address";
  return null;
}

export function validateName(name: string): string | null {
  const value = name.trim();
  if (!value) return "Please enter your name";
  if (value.length < 2) return "Please enter your name";
  if (value.length > 80) return "Name is too long";
  return null;
}

export function validateContact(form: Record<string, string>): string | null {
  if (form.firstName.trim().length < 2) return "First name is required";
  if (form.lastName.trim().length > 80) return "Last name is too long";
  const emailError = validateEmail(form.email);
  if (emailError) return emailError;
  if (form.phone.trim().length > 20) return "Phone number is too long";
  if (form.organization.trim().length < 2)
    return "Organization is required";
  if (form.organization.trim().length > 120)
    return "Organization name is too long";
  if (form.eventDate.trim().length > 2000)
    return "Message is too long";
  return null;
}